t.script:
                    var selectedPayment = 'cash';
                    var searchTimer = null;
                    var logSearchTimer = null;
                    var activeIndex = -1;
                    var partnerActionId = ;
                    var logCurrentPage = 1;
                    var logPageSize = 20;
                    var logCurrentSearch = '';

                    function rpc(url, params) {
                        return fetch(url, {
                            method: 'POST',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params, id: Date.now()}),
                            credentials: 'same-origin',
                        }).then(function(r) { return r.json(); }).then(function(d) { return d.result; });
                    }

                    function debounceSearchLog() {
                        if (logSearchTimer) clearTimeout(logSearchTimer);
                        logSearchTimer = setTimeout(function() {
                            logCurrentSearch = document.getElementById('tcg_log_search').value.trim();
                            logCurrentPage = 1;
                            loadRecentIntakes();
                        }, 300);
                    }

                    function renderLogPagination(page, pageCount, total) {
                        var container = document.getElementById('tcg_log_pagination');
                        container.innerHTML = '';
                        if (pageCount == 1) return;
                        var prevBtn = document.createElement('button');
                        prevBtn.className = 'tcg-log-page-btn';
                        prevBtn.textContent = 'Prev';
                        prevBtn.disabled = page == 1;
                        prevBtn.onclick = function() { loadRecentIntakes(page - 1); };
                        container.appendChild(prevBtn);
                        for (var i = 1; i < pageCount + 1; i++) {
                            var pageBtn = document.createElement('button');
                            pageBtn.className = 'tcg-log-page-btn';
                            pageBtn.textContent = i;
                            if (i == page) {
                                pageBtn.style.background = '#2c6fbb';
                                pageBtn.style.color = 'white';
                                pageBtn.style.borderColor = '#2c6fbb';
                            }
                            pageBtn.onclick = (function(p) {
                                return function() { loadRecentIntakes(p); };
                            })(i);
                            container.appendChild(pageBtn);
                        }
                        var nextBtn = document.createElement('button');
                        nextBtn.className = 'tcg-log-page-btn';
                        nextBtn.textContent = 'Next';
                        nextBtn.disabled = page == pageCount;
                        nextBtn.onclick = function() { loadRecentIntakes(page + 1); };
                        container.appendChild(nextBtn);
                    }

                    function loadRecentIntakes(page) {
                        page = page || logCurrentPage;
                        logCurrentPage = page;
                        rpc('/tcg/aankoop/get_recent_intakes', {
                            page: page,
                            limit: logPageSize,
                            search: logCurrentSearch,
                        }).then(function(data) {
                            var section = document.getElementById('tcg_log_section');
                            var list = document.getElementById('tcg_log_list');
                            var results = data.entries || [];
                            section.style.display = 'block';
                            list.innerHTML = '';
                            if (!results || results.length === 0) {
                                list.innerHTML = '
No results found';
                                renderLogPagination(1, 1, 0);
                                return;
                            }
                            results.forEach(function(r) {
                                var amountStr = r.amount > 0 ? ('€ ' + r.amount.toFixed(2)) : '';
                                var desc = r.description || r.name;
                                var item = document.createElement('div');
                                item.className = 'tcg-log-item';
                                var row = document.createElement('div');
                                row.className = 'tcg-log-row';
                                var badgeWrap = document.createElement('div');
                                var badge = document.createElement('span');
                                badge.className = 'tcg-log-badge buy_in';
                                badge.textContent = 'Buy-in';
                                badgeWrap.appendChild(badge);
                                row.appendChild(badgeWrap);
                                var info = document.createElement('div');
                                info.className = 'tcg-log-info';
                                var nameEl = document.createElement('div');
                                nameEl.className = 'tcg-log-name';
                                nameEl.textContent = desc;
                                info.appendChild(nameEl);
                                var detailEl = document.createElement('div');
                                detailEl.className = 'tcg-log-detail';
                                detailEl.textContent = r.partner_name + (r.employee_name ? ' • ' + r.employee_name : '');
                                info.appendChild(detailEl);
                                var dateEl = document.createElement('div');
                                dateEl.className = 'tcg-log-date';
                                dateEl.textContent = r.date ? r.date.substring(0, 16).replace('T', ' ') : '';
                                info.appendChild(dateEl);
                                row.appendChild(info);
                                if (amountStr) {
                                    var amountEl = document.createElement('div');
                                    amountEl.className = 'tcg-log-amount';
                                    amountEl.textContent = amountStr;
                                    row.appendChild(amountEl);
                                }
                                item.appendChild(row);
                                var linksDiv = document.createElement('div');
                                linksDiv.className = 'tcg-log-links';
                                if (r.po_url) {
                                    var poLink = document.createElement('a');
                                    poLink.href = r.po_url;
                                    poLink.target = '_blank';
                                    poLink.className = 'tcg-log-link po';
                                    poLink.textContent = 'PO ' + (r.po_name || '');
                                    linksDiv.appendChild(poLink);
                                }
                                if (r.bill_url) {
                                    var billLink = document.createElement('a');
                                    billLink.href = r.bill_url;
                                    billLink.target = '_blank';
                                    billLink.className = 'tcg-log-link bill';
                                    billLink.textContent = 'Bill ' + (r.bill_name || '');
                                    linksDiv.appendChild(billLink);
                                }
                                if (r.bill_print_url) {
                                    var printLink = document.createElement('a');
                                    printLink.href = r.bill_print_url;
                                    printLink.target = '_blank';
                                    printLink.className = 'tcg-log-link print';
                                    printLink.textContent = 'Print Bill';
                                    linksDiv.appendChild(printLink);
                                }
                                if (r.ewallet_url) {
                                    var ewLink = document.createElement('a');
                                    ewLink.href = r.ewallet_url;
                                    ewLink.target = '_blank';
                                    ewLink.className = 'tcg-log-link ewallet';
                                    ewLink.textContent = 'eWallet ' + (r.ewallet_code || '');
                                    linksDiv.appendChild(ewLink);
                                }
                                item.appendChild(linksDiv);
                                if (r.payment_method) {
                                    var paymentBadge = document.createElement('div');
                                    paymentBadge.className = 'tcg-log-payment-badge ' + r.payment_method;
                                    if (r.payment_method === 'cash') {
                                        paymentBadge.textContent = '\uD83D\uDCB5 Cash';
                                    } else if (r.payment_method === 'wire_transfer') {
                                        paymentBadge.textContent = '\uD83C\uDFE6 Wire Transfer';
                                    } else if (r.payment_method === 'store_credit') {
                                        paymentBadge.textContent = '\uD83D\uDCB3 e-Wallet';
                                    }
                                    item.appendChild(paymentBadge);
                                }
                                list.appendChild(item);
                            });
                            renderLogPagination(data.page, data.page_count, data.total);
                        });
                    }

                    function selectPayment(method) {
                        selectedPayment = method;
                        document.querySelectorAll('.tcg-payment-option').forEach(function(el) {
                            el.classList.toggle('selected', el.getAttribute('data-method') === method);
                        });
                        var dateField = document.getElementById('tcg_wire_date_field');
                        if (method === 'wire_transfer') {
                            dateField.classList.add('visible');
                            var input = document.getElementById('tcg_wire_due_date');
                            if (!input.value) {
                                var d = new Date();
                                d.setMonth(d.getMonth() + 1);
                                input.value = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
                            }
                        } else {
                            dateField.classList.remove('visible');
                        }
                    }

                    function loadStaticDropdowns() {
                        Promise.all([
                            rpc('/tcg/aankoop/get_employees', {}),
                            rpc('/tcg/aankoop/get_picking_types', {}),
                        ]).then(function(results) {
                            var employees = results[0] || [];
                            var pickingTypes = results[1] || [];

                            var eSel = document.getElementById('tcg_employee');
                            eSel.innerHTML = '';
                            var eDefault = document.createElement('option');
                            eDefault.value = '';
                            eDefault.textContent = 'Select employee...';
                            eSel.appendChild(eDefault);
                            employees.forEach(function(e) {
                                var opt = document.createElement('option');
                                opt.value = e.id;
                                opt.textContent = e.name + (e.department_name ? ' - ' + e.department_name : '');
                                eSel.appendChild(opt);
                            });

                            var ptSel = document.getElementById('tcg_picking_type');
                            ptSel.innerHTML = '';
                            var ptDefault = document.createElement('option');
                            ptDefault.value = '';
                            ptDefault.textContent = 'Select operation type...';
                            ptSel.appendChild(ptDefault);
                            pickingTypes.forEach(function(pt) {
                                var opt = document.createElement('option');
                                opt.value = pt.id;
                                opt.textContent = pt.name + (pt.warehouse_name ? ' (' + pt.warehouse_name + ')' : '');
                                ptSel.appendChild(opt);
                            });
                        });
                    }

                    var partnerInput = document.getElementById('tcg_partner_input');
                    var partnerDropdown = document.getElementById('tcg_partner_dropdown');
                    var partnerIdField = document.getElementById('tcg_partner_id');

                    partnerInput.addEventListener('input', function() {
                        var term = this.value.trim();
                        if (searchTimer) clearTimeout(searchTimer);
                        if (term.length < 1) { partnerDropdown.classList.remove('open'); return; }
                        searchTimer = setTimeout(function() {
                            rpc('/tcg/aankoop/search_partner', {term: term}).then(function(results) {
                                activeIndex = -1;
                                partnerDropdown.innerHTML = '';
                                results.forEach(function(r) {
                                    var div = document.createElement('div');
                                    div.className = 'tcg-autocomplete-item';
                                    div.setAttribute('data-id', r.id);
                                    div.setAttribute('data-name', r.name);
                                    div.textContent = r.name;
                                    div.addEventListener('click', function() { selectPartner(r.id, r.name); });
                                    partnerDropdown.appendChild(div);
                                });
                                if (term.length >= 1) {
                                    var createDiv = document.createElement('div');
                                    createDiv.className = 'tcg-autocomplete-create';
                                    createDiv.textContent = 'Create new partner in Odoo \u2197';
                                    createDiv.addEventListener('click', function() {
                                        window.open('/odoo/action-' + partnerActionId + '/new', '_blank');
                                        partnerDropdown.classList.remove('open');
                                    });
                                    partnerDropdown.appendChild(createDiv);
                                }
                                partnerDropdown.classList.add('open');
                            });
                        }, 300);
                    });

                    partnerInput.addEventListener('keydown', function(ev) {
                        var items = partnerDropdown.querySelectorAll('.tcg-autocomplete-item');
                        if (ev.key === 'ArrowDown') { ev.preventDefault(); activeIndex = Math.min(activeIndex + 1, items.length - 1); highlightItem(items); }
                        else if (ev.key === 'ArrowUp') { ev.preventDefault(); activeIndex = Math.max(activeIndex - 1, 0); highlightItem(items); }
                        else if (ev.key === 'Enter' && activeIndex >= 0 && items[activeIndex]) { ev.preventDefault(); items[activeIndex].click(); }
                        else if (ev.key === 'Escape') { partnerDropdown.classList.remove('open'); }
                    });

                    function highlightItem(items) {
                        items.forEach(function(it, i) { it.classList.toggle('active', i === activeIndex); });
                    }

                    function selectPartner(id, name) {
                        partnerIdField.value = id;
                        partnerInput.value = '';
                        partnerInput.style.display = 'none';
                        partnerDropdown.classList.remove('open');
                        document.getElementById('tcg_partner_selected_name').textContent = name;
                        document.getElementById('tcg_partner_selected').classList.add('show');
                        var editLink = document.getElementById('tcg_partner_edit_link');
                        editLink.href = '/odoo/action-' + partnerActionId + '/' + id;
                        editLink.style.display = 'inline';
                    }

                    function clearPartner() {
                        partnerIdField.value = '';
                        document.getElementById('tcg_partner_selected').classList.remove('show');
                        document.getElementById('tcg_partner_edit_link').style.display = 'none';
                        partnerInput.style.display = '';
                        partnerInput.value = '';
                        partnerInput.focus();
                    }

                    function escapeHtml(text) {
                        var div = document.createElement('div');
                        div.appendChild(document.createTextNode(text));
                        return div.innerHTML;
                    }

                    document.addEventListener('click', function(ev) {
                        if (!document.getElementById('tcg_partner_ac').contains(ev.target)) {
                            partnerDropdown.classList.remove('open');
                        }
                    });

                    function showForm() {
                        document.getElementById('tcg_tiles_view').classList.add('hidden');
                        document.getElementById('tcg_form_view').classList.add('active');
                        document.getElementById('tcg_progress_view').classList.remove('active');
                        document.getElementById('tcg_result_view').classList.remove('active');
                        document.getElementById('tcg_buyin_fields').style.display = 'block';
                        document.getElementById('tcg_form_error').style.display = 'none';
                        clearPartner();
                        selectPayment('cash');
                        document.getElementById('tcg_wire_due_date').value = '';
                        loadStaticDropdowns();
                        initSignatureCanvas();
                        partnerInput.focus();
                    }

                    function hideForm() {
                        document.getElementById('tcg_tiles_view').classList.remove('hidden');
                        document.getElementById('tcg_form_view').classList.remove('active');
                        document.getElementById('tcg_progress_view').classList.remove('active');
                        document.getElementById('tcg_result_view').classList.remove('active');
                        document.getElementById('tcg_form_error').style.display = 'none';
                        loadRecentIntakes();
                    }

                    function showProgress(steps) {
                        document.getElementById('tcg_form_view').classList.remove('active');
                        document.getElementById('tcg_progress_view').classList.add('active');
                        var container = document.getElementById('tcg_progress_steps');
                        container.innerHTML = '';
                        steps.forEach(function(step, i) {
                            var div = document.createElement('div');
                            div.className = 'tcg-progress-step ' + (i === 0 ? 'current' : 'pending');
                            div.setAttribute('data-step', i);
                            div.textContent = step;
                            container.appendChild(div);
                        });
                    }

                    function updateProgress(currentIdx) {
                        document.querySelectorAll('.tcg-progress-step').forEach(function(el, i) {
                            if (i < currentIdx) { el.className = 'tcg-progress-step done'; }
                            else if (i === currentIdx) { el.className = 'tcg-progress-step current'; }
                            else { el.className = 'tcg-progress-step pending'; }
                        });
                    }

                    function hideCashModal() {
                        document.getElementById('tcg_cash_modal').classList.remove('active');
                    }

                    function showResult(title, rows, links, warnings, isCash) {
                        document.getElementById('tcg_progress_view').classList.remove('active');
                        document.getElementById('tcg_result_view').classList.add('active');
                        document.getElementById('tcg_result_title').textContent = title;
                        var details = document.getElementById('tcg_result_details');
                        details.innerHTML = '';
                        rows.forEach(function(row) {
                            var div = document.createElement('div');
                            div.className = 'tcg-result-row';
                            var labelSpan = document.createElement('span');
                            labelSpan.className = 'tcg-result-row-label';
                            labelSpan.textContent = row.label;
                            var valueSpan = document.createElement('span');
                            valueSpan.className = 'tcg-result-row-value';
                            valueSpan.textContent = row.value;
                            div.appendChild(labelSpan);
                            div.appendChild(valueSpan);
                            details.appendChild(div);
                        });
                        var warningEl = document.getElementById('tcg_result_warning');
                        if (warnings && warnings.length > 0) {
                            warningEl.innerHTML = '';
                            if (isCash) {
                                var cashDiv = document.createElement('div');
                                cashDiv.className = 'tcg-result-cash-warning';
                                warnings.forEach(function(w, idx) {
                                    if (idx > 0) { cashDiv.appendChild(document.createElement('br')); }
                                    cashDiv.appendChild(document.createTextNode('\u26A0 ' + w));
                                });
                                var smallDiv = document.createElement('div');
                                smallDiv.className = 'cash-warning-small';
                                smallDiv.textContent = 'Please open the POS register, click "Cash-out", and use the text above as the reason/reference.';
                                cashDiv.appendChild(smallDiv);
                                warningEl.appendChild(cashDiv);
                            } else {
                                warnings.forEach(function(w, idx) {
                                    if (idx > 0) { warningEl.appendChild(document.createElement('br')); }
                                    warningEl.appendChild(document.createTextNode('\u26A0 ' + w));
                                });
                            }
                            warningEl.style.display = 'block';
                        } else {
                            warningEl.style.display = 'none';
                        }
                        var linksEl = document.getElementById('tcg_result_links');
                        linksEl.innerHTML = '';
                        links.forEach(function(link) {
                            var a = document.createElement('a');
                            a.href = link.url;
                            a.target = '_blank';
                            a.className = 'tcg-result-link' + (link.cls ? ' ' + link.cls : '');
                            a.textContent = link.label;
                            linksEl.appendChild(a);
                        });
                    }

                    var sigCanvas = document.getElementById('tcg_signature_canvas');
                    var sigCtx = sigCanvas.getContext('2d');
                    var sigDrawing = false;
                    var sigHasContent = false;

                    function initSignatureCanvas() {
                        var box = document.getElementById('tcg_sig_box');
                        var rect = box.getBoundingClientRect();
                        var dpr = window.devicePixelRatio || 1;
                        sigCanvas.width = rect.width * dpr;
                        sigCanvas.height = 150 * dpr;
                        sigCanvas.style.width = rect.width + 'px';
                        sigCanvas.style.height = '150px';
                        sigCtx.scale(dpr, dpr);
                        sigCtx.strokeStyle = '#333';
                        sigCtx.lineWidth = 2;
                        sigCtx.lineCap = 'round';
                        sigCtx.lineJoin = 'round';
                        sigHasContent = false;
                        document.getElementById('tcg_sig_placeholder').classList.remove('hidden');
                        document.getElementById('tcg_sig_box').classList.remove('has-signature');
                    }

                    function getSigPos(e) {
                        var rect = sigCanvas.getBoundingClientRect();
                        var cx = e.touches ? e.touches[0].clientX : e.clientX;
                        var cy = e.touches ? e.touches[0].clientY : e.clientY;
                        return { x: cx - rect.left, y: cy - rect.top };
                    }

                    function sigStartDraw(e) {
                        e.preventDefault();
                        sigDrawing = true;
                        var pos = getSigPos(e);
                        sigCtx.beginPath();
                        sigCtx.moveTo(pos.x, pos.y);
                    }
                    function sigDraw(e) {
                        if (!sigDrawing) return;
                        e.preventDefault();
                        var pos = getSigPos(e);
                        sigCtx.lineTo(pos.x, pos.y);
                        sigCtx.stroke();
                        if (!sigHasContent) {
                            sigHasContent = true;
                            document.getElementById('tcg_sig_placeholder').classList.add('hidden');
                            document.getElementById('tcg_sig_box').classList.add('has-signature');
                        }
                    }
                    function sigStopDraw(e) {
                        if (e) e.preventDefault();
                        sigDrawing = false;
                    }

                    sigCanvas.addEventListener('mousedown', sigStartDraw);
                    sigCanvas.addEventListener('mousemove', sigDraw);
                    sigCanvas.addEventListener('mouseup', sigStopDraw);
                    sigCanvas.addEventListener('mouseleave', sigStopDraw);
                    sigCanvas.addEventListener('touchstart', sigStartDraw, {passive: false});
                    sigCanvas.addEventListener('touchmove', sigDraw, {passive: false});
                    sigCanvas.addEventListener('touchend', sigStopDraw, {passive: false});

                    function clearSignature() {
                        var dpr = window.devicePixelRatio || 1;
                        sigCtx.clearRect(0, 0, sigCanvas.width / dpr, sigCanvas.height / dpr);
                        sigHasContent = false;
                        document.getElementById('tcg_sig_placeholder').classList.remove('hidden');
                        document.getElementById('tcg_sig_box').classList.remove('has-signature');
                    }

                    function getSignatureBase64() {
                        if (!sigHasContent) return '';
                        return sigCanvas.toDataURL('image/png').split(',')[1];
                    }

                    function clearFormError() {
                        document.getElementById('tcg_form_error').style.display = 'none';
                    }
                    document.getElementById('tcg_employee').addEventListener('change', clearFormError);
                    document.getElementById('tcg_picking_type').addEventListener('change', clearFormError);
                    document.getElementById('tcg_description').addEventListener('input', clearFormError);
                    document.getElementById('tcg_qty').addEventListener('input', clearFormError);
                    document.getElementById('tcg_total_price').addEventListener('input', clearFormError);

                    function submitForm() {
                        var partnerId = parseInt(document.getElementById('tcg_partner_id').value);
                        var employeeId = parseInt(document.getElementById('tcg_employee').value) || null;
                        var pickingTypeId = parseInt(document.getElementById('tcg_picking_type').value);
                        var errorEl = document.getElementById('tcg_form_error');
                        errorEl.style.display = 'none';

                        if (!partnerId || !employeeId || !pickingTypeId) {
                            var missing = [];
                            if (!partnerId) missing.push('Partner');
                            if (!employeeId) missing.push('Employee');
                            if (!pickingTypeId) missing.push('Operation Type');
                            errorEl.textContent = missing.join(', ') + ' required.';
                            errorEl.style.display = 'block';
                            return;
                        }

                        var desc = document.getElementById('tcg_description').value.trim();
                        if (!desc) {
                            errorEl.textContent = 'Description is required.';
                            errorEl.style.display = 'block';
                            return;
                        }
                        var signatureData = getSignatureBase64();
                        if (!signatureData) {
                            errorEl.textContent = 'Customer signature is required.';
                            errorEl.style.display = 'block';
                            return;
                        }
                        submitBuyIn(partnerId, employeeId, pickingTypeId, signatureData);
                    }

                    function submitBuyIn(partnerId, employeeId, pickingTypeId, signatureData) {
                        var productQty = parseFloat(document.getElementById('tcg_qty').value) || 1.0;
                        var totalPrice = parseFloat(document.getElementById('tcg_total_price').value) || 0.0;
                        var priceUnit = productQty > 0 ? totalPrice / productQty : 0.0;
                        var description = document.getElementById('tcg_description').value.trim();
                        var steps = [
                            'Creating Purchase Order...',
                            'Confirming PO...',
                            'Validating receipt...',
                            'Creating vendor bill...',
                            'Posting bill...',
                            selectedPayment === 'wire_transfer' ? 'Sending payment email...' : 'Settling payment...',
                        ];

                        var btn = document.getElementById('tcg_submit_btn');
                        btn.disabled = true;

                        showProgress(steps);
                        var stepIdx = 0;
                        var progressTimer = setInterval(function() {
                            stepIdx++;
                            if (stepIdx < steps.length) { updateProgress(stepIdx); }
                        }, 600);

                        var rpcParams = {
                            partner_id: partnerId,
                            picking_type_id: pickingTypeId,
                            employee_id: employeeId,
                            product_qty: productQty,
                            price_unit: priceUnit,
                            payment_method: selectedPayment,
                            description: description,
                            signature: signatureData,
                        };
                        if (selectedPayment === 'wire_transfer') {
                            var dueDate = document.getElementById('tcg_wire_due_date').value;
                            if (dueDate) rpcParams.invoice_date_due = dueDate;
                        }
                        rpc('/tcg/aankoop/process_buy_in', rpcParams).then(function(result) {
                            clearInterval(progressTimer);
                            btn.disabled = false;
                            if (result.success) {
                                updateProgress(steps.length);
                                var paymentLabel;
                                if (result.result.payment_method === 'cash') { paymentLabel = 'Cash'; }
                                else if (result.result.payment_method === 'wire_transfer') { paymentLabel = 'Wire Transfer'; }
                                else { paymentLabel = 'Store Credit (eWallet)'; }
                                var rows = [
                                    {label: 'Purchase Order', value: result.result.po_name},
                                    {label: 'Vendor Bill', value: result.result.bill_name},
                                    {label: 'Amount', value: '\u20AC ' + (result.result.amount || 0).toFixed(2)},
                                    {label: 'Payment', value: paymentLabel},
                                ];
                                if (result.result.payment_name) {
                                    rows.push({label: 'Payment Ref', value: result.result.payment_name});
                                }
                                if (result.result.ewallet_code) {
                                    rows.push({label: 'eWallet Code', value: result.result.ewallet_code});
                                    rows.push({label: 'eWallet Balance', value: '\u20AC ' + (result.result.ewallet_balance || 0).toFixed(2)});
                                }
                                var warnings = [];
                                if (result.result.cash_out_note) {
                                    warnings.push('Cash-out from POS register required: ' + result.result.cash_out_note);
                                }
                                if (result.result.warning) {
                                    warnings.push(result.result.warning);
                                }
                                var links = [];
                                if (result.result.po_url) {
                                    links.push({label: 'View Purchase Order', url: result.result.po_url});
                                }
                                if (result.result.bill_url) {
                                    links.push({label: 'View Vendor Bill', url: result.result.bill_url, cls: 'secondary'});
                                }
                                if (result.result.ewallet_url) {
                                    links.push({label: 'View eWallet', url: result.result.ewallet_url, cls: 'tertiary'});
                                }
                                var isCash = result.result.payment_method === 'cash';
                                showResult('Buy-in Complete!', rows, links, warnings, isCash);
                                if (isCash && result.result.cash_out_note) {
                                    var cashNote = result.result.cash_out_note;
                                    var amount = cashNote.split(' (')[0];
                                    var refMatch = cashNote.match(/\(([^)]+)\)/);
                                    var ref = refMatch ? refMatch[1] : '';
                                    document.getElementById('tcg_cash_modal_amount').textContent = amount;
                                    document.getElementById('tcg_cash_modal_ref_text').textContent = 'Reference: ' + ref;
                                    document.getElementById('tcg_cash_modal_ref').textContent = '\u26A0 Cash-out from POS register required: ' + cashNote;
                                    document.getElementById('tcg_cash_modal').classList.add('active');
                                }
                            } else {
                                document.getElementById('tcg_progress_view').classList.remove('active');
                                document.getElementById('tcg_form_view').classList.add('active');
                                var err = document.getElementById('tcg_form_error');
                                err.textContent = result.error || 'Failed to process buy-in.';
                                err.style.display = 'block';
                            }
                        }).catch(function(errObj) {
                            clearInterval(progressTimer);
                            btn.disabled = false;
                            document.getElementById('tcg_progress_view').classList.remove('active');
                            document.getElementById('tcg_form_view').classList.add('active');
                            var err = document.getElementById('tcg_form_error');
                            err.textContent = 'Network error. Please try again.';
                            err.style.display = 'block';
                        });
                    }

                    loadRecentIntakes();
